#!/usr/bin/env python3
"""Patch 24: pinned card headers use a scroll-edge effect - clear at rest, solid with a
soft fade only while content passes beneath - instead of a blurred material. Frontend only.
Run from the repository root with patches 05-23 applied. Checked against the exact files it
was written for; nothing is written unless all of it matches."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/App.jsx': {'before': 'd9cc93791c32113488e49956f3eeeec4f7e7c2fb9937e65ff92a0a457ccf4c09', 'after': 'import { Suspense, lazy, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport CandidateRankingCard from \'./cards/CandidateRankingCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  const [incidentId, setIncidentId] = useState(\'case_0001\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={setIncidentId} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <CaseSwitcher incidents={incidents} active={incidentId} onSelect={setIncidentId} />\n        </aside>\n\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <CandidateRankingCard kind="replay" attribution={vc.attribution} baseline={vc.baseline} />\n                <CandidateRankingCard kind="baseline" attribution={vc.attribution} baseline={vc.baseline} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} />\n                <ForecastCard forecast={vc.forecast} />\n                <NextObservationCard nextObs={vc.next_observation} />\n                <CoverageCard coverage={vc.coverage} />\n                <ProvenanceCard meta={meta} report={shown.report} />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/shell.css': {'before': 'c9a038d388b76d66cea1f59041734c0d9c302c173e308bc1cbd25f42e4d6e301', 'after': '/*\n * App shell, in the manner of a native macOS window: a unified translucent\n * toolbar, a vibrant source-list sidebar with one selection that slides\n * between rows, a content column of sections divided by hairlines rather than\n * boxed cards, and a translucent inspector.\n *\n * Tokens come from index.css. Nothing here is case-specific: panels keep\n * their own internal styles in dashboard.css and inherit the theme through\n * the aliased legacy variables.\n */\n\n/* ----------------------------------------------------------------- window */\n\n.app-shell {\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  background: var(--window-bg);\n}\n\n.finder-layout {\n  display: flex;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.finder-content {\n  flex: 1;\n  display: flex;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------- toolbar */\n\n.topbar {\n  position: relative;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: var(--space-4);\n  height: 52px;\n  padding: 0 var(--space-4) 0 var(--space-5);\n  flex-shrink: 0;\n  background: var(--material-bar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-bottom: 1px solid var(--separator);\n}\n\n.wordmark {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  min-width: 0;\n  white-space: nowrap;\n  font-family: var(--font-body);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.003em;\n  color: var(--label-1);\n}\n\n.wordmark-mark {\n  width: 18px;\n  height: 18px;\n  flex: 0 0 auto;\n  border-radius: 5px;\n}\n\n.wordmark-sub {\n  font-weight: var(--font-weight-normal);\n  color: var(--label-2);\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.topbar-trailing {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  margin-left: auto;\n}\n\n.topbar-meta {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n/* ---------------------------------------------------------------- badges */\n\n.tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 20px;\n  padding: 0 var(--space-2);\n  border: 0;\n  border-radius: 999px;\n  background: var(--fill-hover);\n  color: var(--label-2);\n  font-family: var(--font-body);\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-medium);\n  letter-spacing: 0.005em;\n  line-height: 1;\n  text-transform: none;\n  white-space: nowrap;\n}\n\n.tag-teal,\n.tag-amber,\n.tag-green,\n.tag-red {\n  font-variant-caps: normal;\n}\n\n.tag-teal::before,\n.tag-amber::before,\n.tag-green::before,\n.tag-red::before {\n  content: "";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: currentColor;\n}\n\n.tag-teal  { color: var(--accent);        background: var(--accent-soft); }\n.tag-amber { color: var(--status-orange); background: var(--status-orange-soft); }\n.tag-green { color: var(--status-green);  background: var(--status-green-soft); }\n.tag-red   { color: var(--status-red);    background: var(--status-red-soft); }\n\n/* ---------------------------------------------------------------- sidebar */\n\n.finder-sidebar {\n  width: 264px;\n  min-width: 264px;\n  flex-shrink: 0;\n  overflow-y: auto;\n  padding: var(--space-3) 10px var(--space-4);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-right: 1px solid var(--separator);\n}\n\n.case-switcher {\n  display: flex;\n  flex-direction: column;\n}\n\n.case-switcher-label {\n  display: block;\n  padding: 6px 10px 6px;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: 0.01em;\n  color: var(--label-3);\n}\n\n.case-list-wrap {\n  position: relative;\n}\n\n.case-list {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* One selection that travels between rows instead of colours swapping. */\n.case-highlight {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: var(--h, 0px);\n  transform: translateY(var(--y, 0px));\n  border-radius: 7px;\n  background: var(--accent);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14), inset 0 0.5px 0 rgba(255, 255, 255, 0.22);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.case-highlight.is-ready {\n  opacity: 1;\n  transition: transform var(--dur-base) var(--ease-spring),\n              height var(--dur-base) var(--ease-spring),\n              opacity var(--dur-fast) ease;\n}\n\n.case-item {\n  position: relative;\n  width: 100%;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 10px;\n  border: 0;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--label-1);\n  font: inherit;\n  text-align: left;\n  cursor: default;\n  transition: background-color var(--dur-fast) ease,\n              color var(--dur-base) var(--ease-out),\n              transform var(--dur-base) var(--ease-spring);\n}\n\n.case-item:hover:not(.is-active) {\n  background: var(--fill-hover);\n}\n\n.case-item:active {\n  transform: scale(0.98);\n  transition-duration: var(--dur-fast), var(--dur-fast), var(--dur-fast);\n}\n\n.case-item.is-active {\n  color: var(--on-accent);\n}\n\n.case-item:focus-visible {\n  outline: 3px solid var(--accent-ring);\n  outline-offset: 0;\n}\n\n.case-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: 1.25;\n}\n\n.case-id {\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.case-description {\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  transition: color var(--dur-base) var(--ease-out);\n}\n\n.case-item.is-active .case-description {\n  color: rgba(255, 255, 255, 0.8);\n}\n\n.case-indicator {\n  flex: 0 0 auto;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  box-shadow: inset 0 0 0 0.5px rgba(0, 0, 0, 0.12);\n  transition: background-color var(--dur-base) var(--ease-out);\n}\n\n.indicator-known   { background: var(--status-green); }\n.indicator-unknown { background: var(--status-orange); }\n\n.case-item.is-active .indicator-known,\n.case-item.is-active .indicator-unknown {\n  background: var(--on-accent);\n}\n\n/* ---------------------------------------------------------------- content */\n\n.finder-features {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: 0 var(--space-7) var(--space-8);\n  background: var(--content-bg);\n}\n\n.finder-features > * {\n  width: 100%;\n  max-width: 1040px;\n  margin-inline: auto;\n}\n\n/* Sections, not cards: no border, fill or shadow; hairlines between them. */\n.panel {\n  flex-shrink: 0;\n  padding: var(--space-6) 0;\n  border: 0;\n  border-top: 1px solid var(--separator);\n  border-radius: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  box-shadow: none;\n}\n\n.panel-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: var(--space-2) var(--space-3);\n  margin-bottom: 14px;\n}\n\n.panel-head h2 {\n  font-family: var(--font-display);\n  font-size: var(--font-size-md);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.012em;\n  color: var(--label-1);\n}\n\n/* Section titles pin while their section scrolls beneath - with a scroll-edge\n   effect, not a translucent material. At rest the header is clear. While its\n   card\'s content passes under it (is-stuck, set by stickyHeaders.js) it takes\n   the pane\'s own solid background, a hairline, and a soft fade below, so\n   content dissolves under it instead of being smeared into a blurred band. */\n.finder-features .panel > .panel-head {\n  position: sticky;\n  top: 0;\n  z-index: 3;\n  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-3)) 14px;\n  padding: var(--space-3) var(--space-3) var(--space-2);\n  background: transparent;\n  transition: background-color 160ms ease, box-shadow 160ms ease;\n}\n.finder-features .panel > .panel-head::after {\n  content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 18px; pointer-events: none;\n  background: linear-gradient(to bottom, var(--content-bg), color-mix(in srgb, var(--content-bg) 0%, transparent));\n  opacity: 0; transition: opacity 160ms ease;\n}\n.finder-features .panel > .panel-head.is-stuck {\n  background: var(--content-bg);\n  box-shadow: 0 0.5px 0 var(--separator);\n}\n.finder-features .panel > .panel-head.is-stuck::after { opacity: 1; }\n\n.finder-features .panel {\n  padding-top: var(--space-6);\n}\n\n.finder-features > .verdict {\n  margin-top: var(--space-6);\n  margin-bottom: var(--space-6);\n}\n\n/* -------------------------------------------------------------- inspector */\n\n.finder-details {\n  width: 340px;\n  min-width: 340px;\n  flex-shrink: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: var(--space-5);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-left: 1px solid var(--separator);\n}\n\n.finder-details .panel {\n  padding: 0;\n  border-top: 0;\n}\n\n.finder-details .console-panel {\n  flex: 1;\n  min-height: 320px;\n  padding: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  border-radius: 0;\n}\n\n.report-buttons {\n  display: flex;\n  gap: var(--space-2);\n  margin-bottom: var(--space-5);\n}\n\n/* ---------------------------------------------------------------- buttons */\n\n.report-button {\n  flex: 1;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 28px;\n  padding: 0 var(--space-3);\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  color: var(--label-1);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: default;\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease;\n}\n\n.report-button:hover {\n  background: var(--control-bg-hover);\n}\n\n.report-button:active {\n  transform: scale(0.97);\n  background: var(--control-bg-pressed);\n  transition-duration: var(--dur-fast);\n}\n\n/* Panel controls: same springs, no lifts, no colour flashes. */\n.suggestion,\n.frag-step,\n.console-input-row button,\n.probe-close,\n.metric-info-trigger {\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease,\n              border-color var(--dur-fast) ease,\n              color var(--dur-fast) ease;\n}\n\n.suggestion {\n  border: 0;\n  border-radius: var(--radius-md);\n  background: var(--surface-sunken);\n  padding: 9px 12px;\n  font-size: var(--font-size-sm);\n  color: var(--label-1);\n  cursor: default;\n}\n\n.suggestion:hover {\n  background: var(--fill-pressed);\n  box-shadow: none;\n  transform: none;\n}\n\n.frag-step {\n  border-radius: var(--radius-sm);\n  background: var(--surface-raised);\n  cursor: default;\n}\n\n.frag-step:hover {\n  background: var(--fill-hover);\n  transform: none;\n}\n\n.console-input-row {\n  border-top: 1px solid var(--separator);\n  padding-top: var(--space-3);\n  margin-top: var(--space-2);\n}\n\n.console-input-row input {\n  height: 28px;\n  padding: 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-sm);\n  transition: box-shadow var(--dur-fast) ease;\n}\n\n.console-input-row input:focus {\n  outline: none;\n  box-shadow: var(--shadow-control), 0 0 0 3px var(--accent-ring);\n}\n\n.console-input-row button {\n  height: 28px;\n  padding: 0 14px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--accent);\n  color: var(--on-accent);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  cursor: default;\n}\n\n.console-input-row button:hover {\n  background: var(--accent-hover);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  transform: none;\n}\n\n.suggestion:active,\n.frag-step:active,\n.console-input-row button:active:not(:disabled),\n.probe-close:active,\n.metric-info-trigger:active {\n  transform: scale(0.96);\n  transition-duration: var(--dur-fast);\n}\n\n/* ------------------------------------------------------------- popovers */\n\n.metric-info-popover {\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--elevated-bg);\n  box-shadow: var(--shadow-float);\n  padding: 10px 12px;\n  animation: popover-in var(--dur-base) var(--ease-spring);\n}\n\n@keyframes popover-in {\n  from { opacity: 0; transform: translateY(-3px) scale(0.98); }\n  to   { opacity: 1; transform: none; }\n}\n\n/* ---------------------------------------------------------- theme control */\n\n.theme-toggle {\n  position: relative;\n  display: inline-grid;\n  grid-auto-flow: column;\n  grid-auto-columns: 30px;\n  height: 24px;\n  padding: 2px;\n  border-radius: 7px;\n  background: var(--fill-hover);\n  box-shadow: inset 0 0 0 0.5px var(--separator);\n}\n\n.theme-toggle-thumb {\n  position: absolute;\n  top: 2px;\n  bottom: 2px;\n  left: 2px;\n  width: 30px;\n  border-radius: 5px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  transform: translateX(calc(var(--i, 0) * 30px));\n  transition: transform var(--dur-base) var(--ease-spring);\n  pointer-events: none;\n}\n\n.theme-seg {\n  position: relative;\n  z-index: 1;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 5px;\n  background: transparent;\n  color: var(--label-2);\n  cursor: default;\n  transition: color var(--dur-fast) ease, transform var(--dur-base) var(--ease-spring);\n}\n\n.theme-seg:hover {\n  color: var(--label-1);\n}\n\n.theme-seg:active {\n  transform: scale(0.92);\n  transition-duration: var(--dur-fast);\n}\n\n.theme-seg[aria-checked="true"] {\n  color: var(--label-1);\n}\n\n.theme-seg svg {\n  width: 14px;\n  height: 14px;\n}\n\n/* ----------------------------------------------------------------- notices */\n\n.error-banner {\n  flex-shrink: 0;\n  margin: var(--space-3) var(--space-5) 0;\n  padding: 10px 14px;\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--status-red-soft);\n  color: var(--status-red);\n  font-size: var(--font-size-sm);\n}\n\n/* -------------------------------------------- materials without vibrancy */\n\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .topbar { background: var(--solid-bar); }\n  .finder-sidebar, .finder-details { background: var(--solid-sidebar); }\n}\n\n@media (prefers-reduced-transparency: reduce) {\n  .topbar { background: var(--solid-bar); backdrop-filter: none; -webkit-backdrop-filter: none; }\n  .finder-sidebar, .finder-details {\n    background: var(--solid-sidebar); backdrop-filter: none; -webkit-backdrop-filter: none;\n  }\n  .finder-features .panel > .panel-head, .finder-features .panel > .panel-head::after { transition: none; }\n}\n\n/* ------------------------------------------------------------- narrow widths */\n\n/* Stacked: one scroll container for the whole page, so the columns flow one\n   after another instead of each clipping its own content. */\n@media (max-width: 1100px) {\n  .finder-layout {\n    flex-direction: column;\n    overflow-y: auto;\n  }\n  .finder-content {\n    flex: none;\n    flex-direction: column;\n    overflow: visible;\n  }\n  .finder-sidebar {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    max-height: 220px;\n    border-right: 0;\n    border-bottom: 1px solid var(--separator);\n  }\n  .finder-features {\n    flex: none;\n    min-height: auto;\n    overflow: visible;\n    padding: 0 var(--space-5) var(--space-6);\n  }\n  .finder-details {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    min-height: auto;\n    overflow: visible;\n    border-left: 0;\n    border-top: 1px solid var(--separator);\n  }\n  .console-panel { height: 420px; }\n}\n\n@media (max-width: 620px) {\n  .topbar { height: auto; flex-wrap: wrap; padding: 10px 14px; }\n  .topbar-trailing { width: 100%; justify-content: space-between; margin-left: 0; }\n  .wordmark-sub { display: none; }\n}\n\n/* the always-visible tour control, and the case cross-fade */\n.tour-btn {\n  height: 28px; padding: 0 12px; border: 0; border-radius: 7px; cursor: default;\n  background: var(--control-bg); color: var(--label-1); box-shadow: var(--shadow-control);\n  font: inherit; font-size: var(--font-size-sm); font-weight: var(--font-weight-medium);\n}\n.tour-btn:hover { background: var(--control-bg-hover); }\n.tour-btn.is-on { background: var(--accent); color: var(--on-accent); }\n.finder-content { transition: opacity 150ms ease; }\n.finder-content.is-leaving { opacity: 0.25; }\n.finder-content > .finder-features, .finder-content > .finder-details { animation: st-case-in 180ms ease; }\n@keyframes st-case-in { from { opacity: 0; } }\n\n@media (prefers-reduced-motion: reduce) {\n  .finder-content > .finder-features, .finder-content > .finder-details { animation: none; }\n}\n'}}
NEW = {'frontend/src/stickyHeaders.js': "/**\n * The scroll-edge effect for pinned card headers, as macOS and iOS do it: a\n * header is clear while its card sits in place, and takes the pane's own solid\n * background - with a hairline and a soft fade below - only while that card's\n * content is actually scrolling beneath it. A translucent blur here smeared\n * whatever passed under it (map imagery, charts) into a textured band.\n */\nexport function attachStickyHeaders(pane) {\n  if (!pane) return () => {};\n  let raf = 0;\n  const update = () => {\n    raf = 0;\n    const top = pane.getBoundingClientRect().top;\n    for (const head of pane.querySelectorAll('.panel > .panel-head')) {\n      const card = head.parentElement.getBoundingClientRect();\n      const h = head.getBoundingClientRect();\n      // stuck: pinned to the pane's top while its card has scrolled past it\n      head.classList.toggle('is-stuck', h.top <= top + 0.5 && card.top < top - 1 && card.bottom > h.bottom);\n    }\n  };\n  const onScroll = () => { if (!raf) raf = requestAnimationFrame(update); };\n  pane.addEventListener('scroll', onScroll, { passive: true });\n  window.addEventListener('resize', onScroll);\n  const ro = new ResizeObserver(onScroll);\n  ro.observe(pane);\n  update();\n  return () => {\n    cancelAnimationFrame(raf);\n    pane.removeEventListener('scroll', onScroll);\n    window.removeEventListener('resize', onScroll);\n    ro.disconnect();\n  };\n}\n"}
CL_OLD = 'has loaded, then fades it in, instead of blanking and reloading.\n'
CL_NEW = "has loaded, then fades it in, instead of blanking and reloading.\n\n**Pinned card headers: a scroll-edge effect instead of a translucent material.** The\nsticky headers carried a permanent blurred material that smeared whatever scrolled\nunder it - map imagery especially - into a textured band. A header is now clear at\nrest, and only while its card's content passes beneath it takes the pane's own solid\nbackground, a hairline and a soft fade below, as macOS and iOS do.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 23 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
